from abc import ABC, abstractmethod

class SortAlgorithm(ABC):
    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, arr, i, j):
        pass

    def sort(self, arr):
        for i in range(len(arr)):
            for j in range(i + 1, len(arr)):
                if self.compare(arr[j], arr[i]) < 0:
                    self.swap(arr, i, j)

class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        return a - b

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]

class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        return a - b

    def swap(self, arr, i, j):
        arr[i], arr[j] = arr[j], arr[i]

# Testing
if __name__ == "__main__":
    # Sort integers
    int_arr = [5, 2, 9, 1, 5]
    bubble = BubbleSort()
    bubble.sort(int_arr)
    print("Bubble Sorted Integers:", int_arr)

    selection = SelectionSort()
    selection.sort(int_arr)
    print("Selection Sorted Integers:", int_arr)

    # Sort strings
    str_arr = ["banana", "apple", "cherry"]
    bubble.sort(str_arr)
    print("Bubble Sorted Strings:", str_arr)

    selection.sort(str_arr)
    print("Selection Sorted Strings:", str_arr)
